use vstd::prelude::*;

verus! {
    /// Given a non-empty vector `x` of f32 values, produce a vector of the same length
    /// whose first and last entries are 0.5 and all other entries are 1.0.
    fn chebweight(x: Vec<f32>) -> (result: Vec<f32>)
        requires
            x.len() > 0,
        ensures
            result.len() == x.len(),
        ensures
            forall |i: usize| i < x.len() ==>
                result[i] == if i == 0 || i + 1 == x.len() { 0.5_f32 } else { 1.0_f32 },
    {
        let n = x.len();
        let mut result: Vec<f32> = Vec::new();
        // optional but avoids reallocations
        result.reserve(n);

        let mut i: usize = 0;
        while i < n
            invariant
                i <= n,
                result.len() == i,
                forall |k: usize| k < i ==>
                    result[k] == if k == 0 || k + 1 == n { 0.5_f32 } else { 1.0_f32 },
            decreases
                n - i,
        {
            let w: f32 = if i == 0 || i + 1 == n {
                0.5_f32
            } else {
                1.0_f32
            };
            result.push(w);
            i += 1;
        }

        result
    }
}

